const KEY='moxom-resolve-20260930';
const ITEMS=[["LX-HC846","GaN PD45W & AVS60W Single USB-C Fast Charger"],["LX-HC844","PD45W&QC27W 2C1A Digital Display Fast Charger"],["LX-HC838","PD67W & QC18W Triple Port Fast Charger (UK Plug)"],["LX-HC836","PD100W & QC60W TFT Display Triple Port Fast Charger"],["LX-HC832","2500W PD70W Worldwide Travel Fast Charger"],["LX-ST808 WL","4 I N 1 Multifunction Wireless Charging Station"],["LX-PB809","PD30W Wired Charging + 25W Wireless Charging 10000mAh Slim Wireless Power Bank"],["LX-PB808","PD35W 10000mAh Dual Built-In Cables & Digital Display Power Bank"],["LX-PB807","3C Certification PD45W QC22.5W 20000mAh Stellar Power Bank"],["LX-VC809","75W Transparent LCD Car Charger"],["LX-VC808","95W 3 Ports Car Charger"],["MX-CL08","Wireless CarPlay Adapter"],["MX-CL10","Wired to Wireless CarPlay Car Receiver"],["MX-VS202","Magnetic Vacuum Phone Holder with Magnetic Ring"],["MX-VS201","Neck Mount Magnetic Holder With Strap Compatible with Phones Action Cameras & More"],["MX-VS198 WL","25W Aluminum Alloy Car Magnetic Wireless Charging Holder"],["LX-CB956","1.5M 240W Type-C Multi-Function Fast Charging Data Cable"],["LX-CB953","1.2M 240W Type-C Digital Display Fast Charge Cable"],["LX-CB943","Type-C to Type-C 1.2M 100W Fast Charging Smart Auto-Off Data Cable"],["MX-HB09","10 IN 1 High Speed USB 3.0 PD100W HUB"],["LX-TW807 ANC+ENC","6MIC ANC+ENC Dual Noise-Canceling TWS In-Ear Wireless Earbuds"],["LX-TW809 ENC","TWS Clip-On 4MIC ENC Noise-Canceling Wireless Earbuds"],["MX-WH32","IP68 Waterproof 1.53 HD Round Screen Smartwatch"],["MX-CP08","Cool Magnetic Semiconductor Mobile Phone Clip-on Radiator"]];
const base='https://www.moxom.com.cn';
const stop=new Set(['the','and','with','for','to','of','a','an','fast','charging','charger','data','cable','uk','type','port','output','plug','wireless','phone']);
const tok=s=>String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(x=>x.length>1&&!stop.has(x));
async function get(url){const r=await fetch(url,{headers:{'user-agent':'Mozilla/5.0','accept-language':'en-US,en;q=0.9'},redirect:'follow',signal:AbortSignal.timeout(20000)});return {status:r.status,url:r.url,text:await r.text()};}
function exactModel(html,model){const plain=html.replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/\s+/g,' ');const esc=model.replace(/[.*+?^$()|[\]\\{}]/g,'\\$&');return new RegExp('(?:Item\\s*No\\.?|Model(?:\\s*No\\.?)?|Model)\\s*[:：]?\\s*'+esc+'(?:\\b|\\s)','i').test(plain)||new RegExp('\\b'+esc+'\\b','i').test(plain);}
function imageUrls(html){const out=[];const push=x=>{try{let u=x.replace(/&amp;/g,'&');if(u.startsWith('//'))u='https:'+u;u=new URL(u,base);if(!/\/products\//i.test(u.pathname))return;if(!/\.(?:jpe?g|png|webp)(?:\.|$)/i.test(u.pathname))return;u.search='';u.pathname=u.pathname.replace(/\.(?:240x240|500x500)\.(jpg|jpeg|png|webp)$/i,'.$1');const href=u.href;if(!out.includes(href))out.push(href);}catch{}};for(const m of html.matchAll(/(?:data-original|data-src|src|content)=["']([^"']+)["']/gi))push(m[1]);return out.slice(0,5);}
function sitemapUrls(xml){return [...xml.matchAll(/<loc>(https?:\/\/[^<]+\/products\/[^<]+)<\/loc>/gi)].map(m=>m[1].replace(/&amp;/g,'&'));}
function score(url,title){const u=new URL(url),slug=tok(u.pathname.split('/').pop()),want=tok(title);const set=new Set(slug);let hits=0;for(const w of want)if(set.has(w))hits++;return want.length?hits/want.length:0;}
async function resolve(model,title,allUrls){let urls=allUrls.map(url=>({url,score:score(url,title)})).filter(x=>x.score>.24).sort((a,b)=>b.score-a.score).slice(0,8).map(x=>x.url);const checked=[];const inspect=async list=>{for(const url of list){if(checked.some(x=>x.url===url))continue;try{const p=await get(url),exact=exactModel(p.text,model);checked.push({url:p.url,status:p.status,exact,title:(p.text.match(/<title[^>]*>([\s\S]*?)<\/title>/i)||[])[1]?.replace(/<[^>]+>/g,' ').trim()||'',images:exact?imageUrls(p.text):[]});if(exact)return true;}catch(e){checked.push({url,status:0,exact:false,error:String(e.message||e),images:[]});}}return false;};let found=await inspect(urls);if(!found){await new Promise(r=>setTimeout(r,500));const s=await get(base+'/search/?Keyword='+encodeURIComponent(model));if(s.status===200){const q=[];for(const m of s.text.matchAll(/href=["']([^"']*\/products\/[^"'?#]+)[^"']*["']/gi)){try{const u=new URL(m[1],base).href;if(!q.includes(u))q.push(u);}catch{}}await inspect(q.slice(0,8));}}return {model,title,exact:checked.filter(x=>x.exact),checked:checked.map(x=>({url:x.url,status:x.status,exact:x.exact,title:x.title}))};}
export default async function handler(req,res){if(String(req.query?.key||'')!==KEY){res.status(404).json({error:'Not found'});return;}try{const sm=await get('https://moxom.com.cn/en-sitemap.xml');const allUrls=sitemapUrls(sm.text);const start=Math.max(0,Number(req.query?.start||0)||0),count=Math.max(1,Math.min(4,Number(req.query?.count||4)||4));const results=[];for(const [model,title] of ITEMS.slice(start,start+count)){results.push(await resolve(model,title,allUrls));await new Promise(r=>setTimeout(r,350));}res.status(200).json({sitemapStatus:sm.status,urlCount:allUrls.length,start,count:results.length,results});}catch(e){res.status(500).json({error:String(e.message||e)});}}